import{_ as t,o as e,c as n,a5 as i}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"UC — Make Payment (PayOs)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/subscription-billing/3-9-3-make-payment-payos/spec.md","filePath":"feature/subscription-billing/3-9-3-make-payment-payos/spec.md"}'),o={name:"feature/subscription-billing/3-9-3-make-payment-payos/spec.md"};function r(c,a,s,h,l,d){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="uc-—-make-payment-payos" tabindex="-1">UC — Make Payment (PayOs) <a class="header-anchor" href="#uc-—-make-payment-payos" aria-label="Permalink to &quot;UC — Make Payment (PayOs)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.9.3</td></tr><tr><td>Feature</td><td>Make Payment (PayOs)</td></tr><tr><td>Domain</td><td>Subscription (FR 3.9)</td></tr><tr><td>Role</td><td>USER</td></tr><tr><td>Version</td><td>2.0 (V2 — nghiệp vụ mới, 2026-09-14)</td></tr><tr><td>Trạng thái tài liệu</td><td>Draft — BA confirmed, chưa code</td></tr></tbody></table><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Tạo Transaction cho các tính năng nâng gói, mua thêm credit — tuân thủ ACID.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>Là một User, tôi muốn thanh toán qua PayOS, để hoàn tất upgrade Plan hoặc mua thêm credit.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ul><li>Tạo <code>Transaction</code> với trạng thái <code>PENDING</code>, redirect sang PayOS checkout.</li><li>Callback từ PayOS xác nhận thanh toán → cập nhật <code>Transaction.status = SUCCESS</code>, kích hoạt hiệu lực Plan/Credit tương ứng.</li><li><strong>Toàn bộ quy trình phải tuân thủ ACID</strong>: nếu callback xử lý giữa đường bị lỗi (ví dụ cập nhật Plan thành công nhưng ghi Transaction log thất bại), phải rollback toàn bộ — không để trạng thái nửa vời (đã tính tiền nhưng chưa cấp Plan, hoặc ngược lại).</li></ul><h2 id="_4-ui-ux" tabindex="-1">4. UI / UX <a class="header-anchor" href="#_4-ui-ux" aria-label="Permalink to &quot;4. UI / UX&quot;">​</a></h2><ul><li>Redirect sang PayOS checkout page, quay lại <code>/settings/subscription/payment-result</code> sau khi thanh toán.</li></ul><h2 id="_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" tabindex="-1">5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật) <a class="header-anchor" href="#_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" aria-label="Permalink to &quot;5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v1/payments/create</span></span>
<span class="line"><span>{ &quot;type&quot;: &quot;upgrade_plan|buy_credit&quot;, &quot;refId&quot;: &quot;string&quot; }</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: { &quot;paymentUrl&quot;, &quot;transactionId&quot; } }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>POST /api/v1/payments/callback (webhook từ PayOS)</span></span>
<span class="line"><span>{ &quot;transactionId&quot;, &quot;status&quot;, &quot;signature&quot; }</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true }</span></span></code></pre></div><h2 id="_6-error-handling" tabindex="-1">6. Error Handling <a class="header-anchor" href="#_6-error-handling" aria-label="Permalink to &quot;6. Error Handling&quot;">​</a></h2><ul><li>Signature webhook không khớp (giả mạo) → 400 <code>INVALID_WEBHOOK_SIGNATURE</code>, không xử lý.</li><li>Thanh toán thất bại từ PayOS → <code>Transaction.status = FAILED</code>, không cấp Plan/Credit.</li></ul><h2 id="_7-edge-cases" tabindex="-1">7. Edge Cases <a class="header-anchor" href="#_7-edge-cases" aria-label="Permalink to &quot;7. Edge Cases&quot;">​</a></h2><ul><li>Webhook gọi lại nhiều lần cho cùng 1 transaction (PayOS retry) → idempotency check theo <code>transactionId</code>, không cấp Plan/Credit trùng lần 2.</li></ul><h2 id="_8-definition-of-done" tabindex="-1">8. Definition of Done <a class="header-anchor" href="#_8-definition-of-done" aria-label="Permalink to &quot;8. Definition of Done&quot;">​</a></h2><ul><li>Thanh toán + kích hoạt Plan/Credit hoạt động đúng ACID, idempotent với webhook retry.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Không có.</li></ul><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../../BA/08-subscription-billing.html">08-subscription-billing.md</a></p>`,22)])])}const b=t(o,[["render",r]]);export{p as __pageData,b as default};
